async (page) => {
  const events = [];
  page.on('pageerror', e => events.push({t:'pageerror', m:e.message}));
  page.on('console', m => { if (m.type()==='error') events.push({t:'console', m:m.text()}); });
  const buttons = await page.locator('button').all();
  const out = [];
  for (const b of buttons) {
    const label = await b.innerText();
    const sec = await b.evaluate(el => (el.closest('section,div,[id]')||el).outerHTML.slice(0,200));
    const start = events.length;
    await b.click();
    await page.waitForTimeout(1500);
    out.push({label, sec, ev: events.slice(start)});
  }
  return out;
}

