    window.addEventListener('unhandledrejection', e => window.__ev.push({t:'rejection', m: String(e.reason && e.reason.message || e.reason), cur: window.__cur}));
  });
  const out = {};
  for (const l of 'ABCDEFGH') {
    await page.evaluate(l => window.__cur = l, l);
    await page.click(`button[data-l="${l}"]`);
    await page.waitForTimeout(4000);
  }
  return await page.evaluate(() => window.__ev);
}

